class DataError(Exception): pass

@st.cache_data(ttl=25,show_spinner=False)
def api(service,operation,key,params):
    """완전한 페이지 조회. 키/요청 URL은 오류에 노출하지 않습니다."""
    all_items=[]
    for page in range(1,101):
        try:
            r=requests.get(BASE+service+'/'+operation,params={'serviceKey':unquote(key.strip()),'_type':'json','numOfRows':100,'pageNo':page,**params},timeout=(5,15))
            if r.status_code!=200: raise DataError('서버 응답 오류 (HTTP '+str(r.status_code)+'). 잠시 후 다시 시도하세요.')
            try: data=r.json()
            except ValueError:
                raise DataError('JSON 응답이 아닙니다. 인증키·활용승인·일일 호출한도를 확인하세요.')
            response=data.get('response',{})
            header=response.get('header',{})
            code=str(header.get('resultCode',''))
            if code not in ('00','0'):
                raise DataError('공공데이터 응답 코드 '+re.sub(r'[^a-zA-Z0-9]','',code)[:20]+'. 인증키·서비스별 활용승인·한도를 확인하세요.')
            body=response.get('body',{})
            raw=body.get('items') or {}
            items=raw.get('item',[]) if isinstance(raw,dict) else []
            if isinstance(items,dict): items=[items]
            all_items.extend(items)
            if len(all_items)>=int(body.get('totalCount',len(all_items))) or not items: return all_items
        except requests.RequestException:
            raise DataError('데이터 서버 연결 지연 또는 장애입니다. 잠시 후 새로고침하세요.') from None
    raise DataError('조회량이 많아 완료하지 못했습니다. 검색어를 좁혀주세요.')

def safe_call(service,operation,key,**params):
    try: return api(service,operation,key,params),None
    except DataError as e: return [],str(e)

def integer(v,default=0):
    try: return int(float(v))
    except (ValueError,TypeError): return default

def coordinates(x):
    try:
        lat,lon=float(x['gpslati']),float(x['gpslong'])
        return (lat,lon) if 32<lat<40 and 124<lon<132 else None
    except (KeyError,TypeError,ValueError): return None

def station_label(s): return f"{s.get('nodenm','이름 없음')} · {s.get('nodeid','')}"

def timetable_records():
    out=[]
    for b in BOOKS:
        s=b['sheets'][0]; rows=s['rows']
        cols=range(1,22,3) if b['name']=='농어촌버스' else range(1,13,3)
        headings={}
        for ri,row in enumerate(rows):
            for c in cols:
                if c+2>=len(row): continue
                place,t,bus=row[c:c+3]
                if place and not t and not bus: headings[c]=place
                if re.fullmatch(r'\d{1,2}:\d{2}(?::\d{2})?',t) and re.fullmatch(r'\d+',bus):
                    out.append({'종류':b['name'],'구분':headings.get(c,''),'시각':t[:5] if len(t.split(':')[0])==2 else '0'+t[:4],'번호':bus,'경유·행선지(원문)':place,'원본 시트':s['name'],'원본 행':ri+1})
    return pd.DataFrame(out).drop_duplicates()

